options.getOption:
const selectedDay = context.grafana.replaceVariables('$selected_day');

function getSeries(refId, labelKey) {
  const frames = context.panel.data.series.filter((s) => s.refId === refId);
  const points = frames.map((frame) => {
    const valueField = frame.fields.find((f) => f.type === 'number');
    const label = (valueField && valueField.labels && valueField.labels[labelKey]) || '';
    const values = valueField ? valueField.values.toArray() : [0];
    return { label: label, value: values[values.length - 1] || 0 };
  }).filter((p) => p.label !== '');
  points.sort((a, b) => a.label.localeCompare(b.label));
  return points;
}

function backButton(onClick) {
  const W = 190, H = 34;
  const BTN_COLOR = '#374151';
  return {
    elements: [
      {
        type: 'group',
        right: 10,
        top: 4,
        z: 100,
        children: [
          {
            type: 'rect',
            shape: { x: 0, y: 0, width: W, height: H, r: 6 },
            style: { fill: BTN_COLOR },
            onclick: onClick,
            cursor: 'pointer'
          },
          {
            type: 'text',
            x: W / 2,
            y: H / 2,
            style: {
              text: '← Quay lại theo ngày',
              fill: '#ffffff',
              fontSize: 13,
              fontWeight: 'bold',
              align: 'center',
              verticalAlign: 'middle'
            },
            onclick: onClick,
            cursor: 'pointer'
          }
        ]
      }
    ]
  };
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const MIN_DAYS = 7;

function toDateLabel(ms) {
  const d = new Date(ms);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

let option;

if (!selectedDay) {
  // ---- VIEW THEO NGÀY: luôn hiển thị tối thiểu 7 ngày, mở rộng nếu time range dài hơn ----
  const fromMs = Number(context.grafana.replaceVariables('$__from'));
  const toMsRaw = Number(context.grafana.replaceVariables('$__to'));
  const toMs = new Date(toDateLabel(toMsRaw) + 'T00:00:00').getTime();

  const valueByDay = {};
  getSeries('A', 'day').forEach((p) => { valueByDay[p.label] = p.value; });

  const rangeDays = Math.round((toMs - new Date(toDateLabel(fromMs) + 'T00:00:00').getTime()) / MS_PER_DAY) + 1;
  const daysToShow = Math.max(MIN_DAYS, rangeDays);

  const points = [];
  for (let i = daysToShow - 1; i >= 0; i--) {
    const label = toDateLabel(toMs - i * MS_PER_DAY);
    points.push({ label: label, value: valueByDay[label] || 0 });
  }

  option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (params) => {
        const p = params[0];
        return 'Ngày ' + p.axisValueLabel + '<br/>Số request: <b>' + p.value + '</b>';
      }
    },
    grid: { left: 55, right: 30, top: 30, bottom: 40, containLabel: true },
    xAxis: { type: 'category', data: points.map((p) => p.label) },
    yAxis: { type: 'value' },
    series: [{
      type: 'bar',
      data: points.map((p) => p.value),
      barCategoryGap: '35%',
      label: { show: true, position: 'top', fontSize: 11 },
      itemStyle: { color: '#73C0DE', borderRadius: [4, 4, 0, 0] }
    }]
  };
  context.panel.chart.off('click');
  context.panel.chart.on('click', (params) => {
    const day = points[params.dataIndex] && points[params.dataIndex].label;
    if (day) {
      context.grafana.locationService.partial({ 'var-selected_day': day }, true);
    }
  });
} else {
  // ---- VIEW THEO GIỜ: đủ 24 giờ của ngày đã chọn, mỗi giờ 1 cột riêng biệt ----
  const raw = getSeries('B', 'hod');
  const byHour = {};
  raw.forEach((p) => { byHour[p.label] = p.value; });
  const hours = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, '0'));
  const values = hours.map((h) => byHour[h] || 0);

  const maxHourVal = Math.max(...values, 1);
  option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (params) => {
        const p = params[0];
        return 'Giờ ' + p.axisValueLabel + '<br/>Số request: <b>' + p.value + '</b>';
      }
    },
    grid: { left: 55, right: 30, top: 55, bottom: 40, containLabel: true },
    graphic: backButton(() => context.grafana.locationService.partial({ 'var-selected_day': '' }, true)),
    xAxis: { type: 'category', data: hours.map((h) => h + 'h') },
    yAxis: { type: 'value', max: Math.ceil(maxHourVal * 1.25) },
    series: [{
      type: 'bar',
      data: values,
      barCategoryGap: '25%',
      label: { show: true, position: 'top', fontSize: 11 },
      itemStyle: { color: '#FAC858', borderRadius: [4, 4, 0, 0] }
    }]
  };
}

return option;

